"use strict";(self.webpackChunkbast_docu=self.webpackChunkbast_docu||[]).push([[7293],{37526:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"release_1.7.0","metadata":{"permalink":"/dadadocu/dadagraves-changelog/release_1.7.0","source":"@site/dadagraves-changelog/2026-6-18-active-gravestones.md","title":"Release 1.7.0 - PREMIUM","description":"This update adds a player-facing Active Gravestones menu and new controls for limiting how many graves a player can keep.","date":"2026-06-18T00:00:00.000Z","tags":[{"inline":true,"label":"dadagraves","permalink":"/dadadocu/dadagraves-changelog/tags/dadagraves"}],"hasTruncateMarker":true,"authors":[{"name":"mrbast","title":"DadaGraves Developer","url":"https://www.spigotmc.org/members/mrbast.610454/","key":"mrbast","page":null}],"frontMatter":{"slug":"release_1.7.0","title":"Release 1.7.0 - PREMIUM","authors":["mrbast"],"tags":["dadagraves"]},"unlisted":false,"nextItem":{"title":"Release 1.6.0 - PREMIUM","permalink":"/dadadocu/dadagraves-changelog/release_1.6.0"}},"content":"This update adds a player-facing Active Gravestones menu and new controls for limiting how many graves a player can keep.\\n\\n\x3c!-- truncate --\x3e\\n\\n### Active Gravestones GUI\\n\\n- Added `/graves history`.\\n- Added a personal GUI button that opens the active gravestones menu.\\n- The menu shows each active grave with useful information such as location, creation time, decay time, lock time, and stored items.\\n\\n### History actions\\n\\n- Added `gravestone.cmd.history` for opening the history menu.\\n- Added `gravestone.history.open-distance` for opening a grave from the history menu.\\n- Added `gravestone.history.teleport` for shift left-click teleport from the history menu.\\n- History item lore now only shows actions the player is allowed to use.\\n\\n### Grave limits\\n\\n- Added `max-graves` to permission groups.\\n- Added `max-graves-action`.\\n- `DROP` removes the oldest grave and drops its contents.\\n- `DELETE` removes the oldest grave together with its contents.\\n\\n### Compatibility\\n\\n- Updated internal platform and text-formatting libraries for the current release line."},{"id":"release_1.6.0","metadata":{"permalink":"/dadadocu/dadagraves-changelog/release_1.6.0","source":"@site/dadagraves-changelog/2026-6-05-1.6.0.md","title":"Release 1.6.0 - PREMIUM","description":"Newest version compatibility","date":"2026-06-05T00:00:00.000Z","tags":[{"inline":true,"label":"dadagraves","permalink":"/dadadocu/dadagraves-changelog/tags/dadagraves"}],"hasTruncateMarker":false,"authors":[{"name":"mrbast","title":"DadaGraves Developer","url":"https://www.spigotmc.org/members/mrbast.610454/","key":"mrbast","page":null}],"frontMatter":{"slug":"release_1.6.0","title":"Release 1.6.0 - PREMIUM","authors":["mrbast"],"tags":["dadagraves"]},"unlisted":false,"prevItem":{"title":"Release 1.7.0 - PREMIUM","permalink":"/dadadocu/dadagraves-changelog/release_1.7.0"}},"content":"### Newest version compatibility\\n\\n- Added support up to Minecraft 26.1.2.\\n\\n### Commands\\n\\n- Added `/graves graveyard set`.\\n- Added `/graves graveyard tp`.\\n- Added tab completion for the new graveyard commands.\\n\\n### Graveyard\\n\\n- Added the graveyard system.\\n- When a player respawns after dying, they are teleported to the graveyard if one has been configured.\\n- If no graveyard is configured, DadaGraves does not change the player\'s respawn location.\\n\\n### Holograms\\n\\n- Improved hologram cleanup when a gravestone is removed.\\n- Removed hologram leftovers more reliably when a grave expires or is deleted."}]}}')}}]);